//! Integration tests for the Axum adapter's stateful (session-based) wiring.
//!
//! `authkestra-engine`'s own tests exercise `AuthMethod`/`Flow`/`Provider`
//! implementations and `OAuth2Flow` directly (see
//! `authkestra-engine/tests/oauth2_flow_tests.rs`). Those tests never touch
//! `authkestra-axum`, so they can't catch adapter-level regressions: state
//! extraction via `FromRef` (generated by `#[derive(AxumState)]`), the
//! `tower_cookies` wiring, or the `AxumError -> Response` mapping.
//!
//! These tests build a real `axum::Router` — the same one an application
//! would build with `Engine::axum_router()` — and drive it with
//! `tower::ServiceExt::oneshot`, asserting on actual HTTP responses (status
//! codes, `Set-Cookie`/`Location` headers, JSON bodies) rather than calling
//! engine internals directly.
//!
//! The OAuth provider is a fully in-process mock (no network, no wiremock)
//! so the flow is deterministic: `authkestra-providers` already has its own
//! wiremock-backed tests for the real provider implementations.

use async_trait::async_trait;
use authkestra_axum::{AuthSession, AxumExt, AxumState};
use authkestra_engine::auth::{
    AuthError, Identity, OAuthProvider, OAuthToken, Provider, ProviderConfig, Session, SessionStore,
};
use authkestra_engine::flow::{Engine, OAuth2Flow};
use authkestra_engine::{AkWebAppEngine, SessionConfig};
use axum::{
    body::Body,
    http::{header, Request, StatusCode},
    response::IntoResponse,
    routing::get,
    Json, Router,
};
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use tower::ServiceExt;
use tower_cookies::CookieManagerLayer;

/// A deterministic, in-process stand-in for a real OAuth2 provider.
///
/// Only `"valid-code"` exchanges successfully, mirroring the pattern used by
/// `authkestra-engine`'s own `oauth2_flow_tests.rs` mock.
struct MockOAuthProvider;

#[async_trait]
impl Provider for MockOAuthProvider {
    async fn config(&self) -> ProviderConfig {
        ProviderConfig {
            id: "mock".to_string(),
            name: "Mock".to_string(),
            extra: HashMap::new(),
        }
    }
}

#[async_trait]
impl OAuthProvider for MockOAuthProvider {
    fn provider_id(&self) -> &str {
        "mock"
    }

    fn get_authorization_url(
        &self,
        state: &str,
        _scopes: &[&str],
        _code_challenge: Option<&str>,
        _nonce: Option<&str>,
    ) -> String {
        format!("https://mock.example.com/authorize?state={state}")
    }

    async fn exchange_code_for_identity(
        &self,
        code: &str,
        _code_verifier: Option<&str>,
        nonce: Option<&str>,
    ) -> Result<(Identity, OAuthToken), AuthError> {
        if code != "valid-code" {
            return Err(AuthError::Token("invalid code".to_string()));
        }

        let mut attributes = HashMap::new();
        // OAuth2Flow::finalize_login rejects the exchange if the identity
        // doesn't echo back the nonce it generated, so a well-behaved
        // provider mock must round-trip it exactly like a real one would.
        if let Some(n) = nonce {
            attributes.insert("nonce".to_string(), n.to_string());
        }

        Ok((
            Identity {
                provider_id: "mock".to_string(),
                external_id: "user-42".to_string(),
                email: Some("user@example.com".to_string()),
                username: Some("mockuser".to_string()),
                attributes,
            },
            OAuthToken {
                access_token: "at-123".to_string(),
                token_type: "Bearer".to_string(),
                expires_in: Some(3600),
                refresh_token: None,
                scope: None,
                id_token: None,
            },
        ))
    }
}

/// A minimal in-memory `SessionStore`, independent of
/// `authkestra_engine::store::memory::MemoryStore` (which sits behind the
/// `memory` feature) so this test only needs the features it declares via
/// `required-features` in `Cargo.toml`.
#[derive(Default)]
struct TestSessionStore {
    sessions: Mutex<HashMap<String, Session>>,
}

#[async_trait]
impl SessionStore for TestSessionStore {
    async fn load_session(&self, id: &str) -> Result<Option<Session>, AuthError> {
        Ok(self.sessions.lock().unwrap().get(id).cloned())
    }

    async fn save_session(&self, session: &Session) -> Result<(), AuthError> {
        self.sessions
            .lock()
            .unwrap()
            .insert(session.id.clone(), session.clone());
        Ok(())
    }

    async fn delete_session(&self, id: &str) -> Result<(), AuthError> {
        self.sessions.lock().unwrap().remove(id);
        Ok(())
    }
}

#[derive(Clone, AxumState)]
struct AppState {
    #[authkestra(engine)]
    auth: AkWebAppEngine,
}

async fn protected(AuthSession(session): AuthSession) -> impl IntoResponse {
    Json(serde_json::json!({
        "external_id": session.identity.external_id,
        "email": session.identity.email,
        "provider": session.identity.provider_id,
    }))
}

/// Builds the same shape of app a real application would: the engine's
/// generated `/auth/login/:provider`, `/auth/callback/:provider`, and
/// `/auth/logout` routes, plus one application route protected by
/// `AuthSession`.
fn build_app() -> Router {
    let session_store: Arc<dyn SessionStore> = Arc::new(TestSessionStore::default());
    let engine = Engine::builder()
        .provider(OAuth2Flow::new(MockOAuthProvider))
        .session_store(session_store)
        .session_config(SessionConfig {
            // The test client talks plain HTTP; a `Secure` cookie would
            // never round-trip back to the server.
            secure: false,
            ..Default::default()
        })
        .build();
    let state = AppState {
        auth: engine.clone(),
    };

    Router::new()
        .route("/protected", get(protected))
        .merge(engine.axum_router())
        .layer(CookieManagerLayer::new())
        .with_state(state)
}

/// Extracts the value of the first `Set-Cookie` header matching `name` from
/// a response (ignoring cookie attributes like `Path`/`HttpOnly`).
fn set_cookie_value(resp: &axum::response::Response, name: &str) -> Option<String> {
    resp.headers()
        .get_all(header::SET_COOKIE)
        .iter()
        .filter_map(|v| v.to_str().ok())
        .find_map(|raw| {
            let (key, value) = raw.split_once(';').unwrap_or((raw, "")).0.split_once('=')?;
            (key == name).then(|| value.to_string())
        })
}

async fn body_json(resp: axum::response::Response) -> serde_json::Value {
    let bytes = axum::body::to_bytes(resp.into_body(), usize::MAX)
        .await
        .unwrap();
    serde_json::from_slice(&bytes).unwrap()
}

#[tokio::test]
async fn protected_route_rejects_request_without_session_cookie() {
    let app = build_app();

    let resp = app
        .oneshot(
            Request::builder()
                .uri("/protected")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(resp.status(), StatusCode::UNAUTHORIZED);
}

#[tokio::test]
async fn full_login_callback_session_and_logout_round_trip() {
    let app = build_app();

    // 1. Login initiates the flow: a redirect to the provider, plus an
    //    encrypted `ak_state` CSRF cookie the callback must see again.
    let login_resp = app
        .clone()
        .oneshot(
            Request::builder()
                .uri("/auth/login/mock")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(login_resp.status(), StatusCode::SEE_OTHER);

    let location = login_resp
        .headers()
        .get(header::LOCATION)
        .unwrap()
        .to_str()
        .unwrap()
        .to_string();
    assert!(
        location.starts_with("https://mock.example.com/authorize?state="),
        "unexpected redirect location: {location}"
    );
    let csrf_state = location.rsplit('=').next().unwrap().to_string();

    let ak_state_cookie =
        set_cookie_value(&login_resp, "ak_state").expect("login must set the ak_state CSRF cookie");

    // 2. Callback: present the CSRF cookie, the matching `state`, and a code
    //    the mock provider accepts.
    let callback_resp = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/auth/callback/mock?code=valid-code&state={csrf_state}"
                ))
                .header(header::COOKIE, format!("ak_state={ak_state_cookie}"))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(callback_resp.status(), StatusCode::SEE_OTHER);

    let session_cookie = set_cookie_value(&callback_resp, "authkestra_session")
        .expect("a successful callback must set the session cookie");

    // 3. The protected route now succeeds and returns the identity that came
    //    back from the (mock) provider.
    let protected_resp = app
        .clone()
        .oneshot(
            Request::builder()
                .uri("/protected")
                .header(
                    header::COOKIE,
                    format!("authkestra_session={session_cookie}"),
                )
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(protected_resp.status(), StatusCode::OK);
    let json = body_json(protected_resp).await;
    assert_eq!(json["external_id"], "user-42");
    assert_eq!(json["email"], "user@example.com");
    assert_eq!(json["provider"], "mock");

    // 4. Logout deletes the session server-side...
    let logout_resp = app
        .clone()
        .oneshot(
            Request::builder()
                .uri("/auth/logout")
                .header(
                    header::COOKIE,
                    format!("authkestra_session={session_cookie}"),
                )
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(logout_resp.status(), StatusCode::SEE_OTHER);

    // 5. ...so presenting the very same session cookie again is rejected.
    let after_logout_resp = app
        .oneshot(
            Request::builder()
                .uri("/protected")
                .header(
                    header::COOKIE,
                    format!("authkestra_session={session_cookie}"),
                )
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(after_logout_resp.status(), StatusCode::UNAUTHORIZED);
}

#[tokio::test]
async fn callback_rejects_mismatched_csrf_state() {
    let app = build_app();

    let login_resp = app
        .clone()
        .oneshot(
            Request::builder()
                .uri("/auth/login/mock")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    let ak_state_cookie = set_cookie_value(&login_resp, "ak_state").unwrap();

    // The `state` query param doesn't match the one encrypted into the
    // `ak_state` cookie: this must be treated as a CSRF failure, not
    // silently accepted.
    let callback_resp = app
        .oneshot(
            Request::builder()
                .uri("/auth/callback/mock?code=valid-code&state=not-the-real-state")
                .header(header::COOKIE, format!("ak_state={ak_state_cookie}"))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(callback_resp.status(), StatusCode::UNAUTHORIZED);
}

#[tokio::test]
async fn callback_rejects_missing_csrf_cookie() {
    let app = build_app();

    // No `ak_state` cookie at all (e.g. the user opened the callback link
    // directly, or cookies were dropped in transit).
    let callback_resp = app
        .oneshot(
            Request::builder()
                .uri("/auth/callback/mock?code=valid-code&state=whatever")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(callback_resp.status(), StatusCode::UNAUTHORIZED);
}

#[tokio::test]
async fn callback_rejects_provider_exchange_failure() {
    let app = build_app();

    let login_resp = app
        .clone()
        .oneshot(
            Request::builder()
                .uri("/auth/login/mock")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    let location = login_resp
        .headers()
        .get(header::LOCATION)
        .unwrap()
        .to_str()
        .unwrap()
        .to_string();
    let csrf_state = location.rsplit('=').next().unwrap().to_string();
    let ak_state_cookie = set_cookie_value(&login_resp, "ak_state").unwrap();

    // A code the mock provider doesn't recognize as valid.
    let callback_resp = app
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/auth/callback/mock?code=wrong-code&state={csrf_state}"
                ))
                .header(header::COOKIE, format!("ak_state={ak_state_cookie}"))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(callback_resp.status(), StatusCode::UNAUTHORIZED);
}

/// An unregistered provider is a client error, not a server fault.
///
/// This returned 500 until #321's sibling fix: `AxumError` had no not-found
/// variant, so the three `providers.get()` misses fell back to `Internal`.
/// The actix adapter answered 404 for the identical condition, so the two
/// adapters disagreed on the HTTP contract for the same request.
/// See https://github.com/marcjazz/authkestra/issues/320.
#[tokio::test]
async fn an_unknown_provider_is_not_found_rather_than_a_server_error() {
    for uri in [
        "/auth/login/nope",
        "/auth/callback/nope?code=valid-code&state=whatever",
    ] {
        let resp = build_app()
            .oneshot(Request::builder().uri(uri).body(Body::empty()).unwrap())
            .await
            .unwrap();

        assert_eq!(
            resp.status(),
            StatusCode::NOT_FOUND,
            "{uri} should be 404, not a 5xx"
        );

        let body = axum::body::to_bytes(resp.into_body(), usize::MAX)
            .await
            .unwrap();
        let body = String::from_utf8(body.to_vec()).unwrap();
        // The name the caller asked for, as actix has always reported it.
        assert!(
            body.contains("nope"),
            "the response should name the provider: {body:?}"
        );
    }
}

/// The 404 body echoes the provider name, which is an unvalidated path
/// segment. Useful, but it must not reflect an unbounded attacker-controlled
/// string, so it is truncated. `authkestra-actix` truncates identically.
#[tokio::test]
async fn a_long_provider_name_is_truncated_in_the_body() {
    let long = "a".repeat(5_000);
    let resp = build_app()
        .oneshot(
            Request::builder()
                .uri(format!("/auth/login/{long}"))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(resp.status(), StatusCode::NOT_FOUND);

    let body = axum::body::to_bytes(resp.into_body(), usize::MAX)
        .await
        .unwrap();
    let body = String::from_utf8(body.to_vec()).unwrap();

    assert!(
        body.len() < 200,
        "the body reflected {} bytes: {body:.120?}",
        body.len()
    );
    assert!(
        body.contains('\u{2026}'),
        "truncation should be visible: {body:?}"
    );
}

/// The registered provider must keep working — a 404 for everything would
/// satisfy the test above just as well.
#[tokio::test]
async fn a_registered_provider_still_redirects() {
    let resp = build_app()
        .oneshot(
            Request::builder()
                .uri("/auth/login/mock")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(resp.status(), StatusCode::SEE_OTHER);
}

// --- OAuth callback failure diagnosis (#353) ---
//
// The three ways a callback can fail — no state cookie, a state cookie that
// will not decrypt, a provider exchange that fails — all return 401 with a
// message the client sees. Nothing distinguished them in the logs, so an
// operator could not tell a browser `SameSite` problem from a rotated
// `state_encryption_key`. These assert they now read differently.

/// Routes each thread's `tracing` output to that thread's own buffer, and
/// discards it on threads that are not capturing.
///
/// A **global** subscriber, installed once, rather than a thread-local one.
/// `tracing` caches callsite interest globally and a thread-local subscriber
/// does not invalidate that cache, so any test reaching a callsite while no
/// subscriber is installed gets its interest cached as "never" — and a later
/// thread-local capture there sees nothing. Rebuilding the cache does not fix
/// it either, because the non-capturing tests run concurrently and re-cache
/// "never" immediately after. Both were tried; both produced a capture that
/// passed alone and failed in a parallel run (#353).
mod capture {
    use std::cell::RefCell;
    use std::io;
    use std::sync::{Arc, Mutex, Once};

    thread_local! {
        static SINK: RefCell<Option<Arc<Mutex<Vec<u8>>>>> = const { RefCell::new(None) };
    }

    #[derive(Clone, Copy, Default)]
    pub struct ThreadSink;

    impl io::Write for ThreadSink {
        fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
            SINK.with(|sink| {
                if let Some(target) = sink.borrow().as_ref() {
                    target.lock().unwrap().extend_from_slice(buf);
                }
            });
            Ok(buf.len())
        }
        fn flush(&mut self) -> io::Result<()> {
            Ok(())
        }
    }

    impl<'a> tracing_subscriber::fmt::MakeWriter<'a> for ThreadSink {
        type Writer = Self;
        fn make_writer(&'a self) -> Self::Writer {
            *self
        }
    }

    static INSTALL: Once = Once::new();

    fn install() {
        INSTALL.call_once(|| {
            let _ = tracing_subscriber::fmt()
                .with_writer(ThreadSink)
                .with_max_level(tracing::Level::TRACE)
                .without_time()
                .try_init();
        });
    }

    /// Starts capturing on this thread; the returned handle yields the output.
    pub struct Handle(Arc<Mutex<Vec<u8>>>);

    impl Handle {
        pub fn contents(&self) -> String {
            String::from_utf8_lossy(&self.0.lock().unwrap()).into_owned()
        }
    }

    impl Drop for Handle {
        fn drop(&mut self) {
            SINK.with(|sink| *sink.borrow_mut() = None);
        }
    }

    pub fn start() -> Handle {
        install();
        let buffer = Arc::new(Mutex::new(Vec::new()));
        SINK.with(|sink| *sink.borrow_mut() = Some(Arc::clone(&buffer)));
        Handle(buffer)
    }
}

/// Drives a callback carrying `state_cookie` (if any) and returns the status
/// alongside everything logged while doing it.
async fn callback_with_state(state_cookie: Option<&str>) -> (StatusCode, String) {
    let captured = capture::start();

    let app = build_app();
    let mut request = Request::builder().uri("/auth/callback/mock?code=valid-code&state=whatever");
    if let Some(cookie) = state_cookie {
        request = request.header(header::COOKIE, format!("ak_state={cookie}"));
    }
    let resp = app
        .oneshot(request.body(Body::empty()).unwrap())
        .await
        .unwrap();

    let status = resp.status();
    let logs = captured.contents();
    (status, logs)
}

#[tokio::test(flavor = "current_thread")]
async fn a_callback_with_no_state_cookie_says_so() {
    let (status, logs) = callback_with_state(None).await;

    assert_eq!(status, StatusCode::UNAUTHORIZED);
    assert!(
        logs.contains("carries no state cookie"),
        "an absent state cookie should be named as such; got:\n{logs}"
    );
    assert!(
        !logs.contains("could not be decrypted"),
        "an absent cookie must not be reported as an undecryptable one:\n{logs}"
    );
}

/// The case worth separating: this is what a rotated `state_encryption_key`
/// looks like, and it is indistinguishable from the one above over HTTP.
#[tokio::test(flavor = "current_thread")]
async fn a_callback_whose_state_cookie_will_not_decrypt_says_so() {
    let (status, logs) = callback_with_state(Some("not-a-valid-encrypted-state")).await;

    assert_eq!(status, StatusCode::UNAUTHORIZED);
    assert!(
        logs.contains("could not be decrypted"),
        "an unreadable state cookie should be named as such; got:\n{logs}"
    );
    assert!(
        logs.contains("state encryption key"),
        "the log should point at key rotation, which is the usual cause; got:\n{logs}"
    );
    assert!(
        !logs.contains("carries no state cookie"),
        "a present-but-unreadable cookie must not be reported as absent:\n{logs}"
    );
}

/// A session store that refuses every write, for the paths a working store
/// never reaches. "The session store is down mid-login" is an ordinary
/// production event and had no test on either adapter.
#[derive(Default)]
struct FailingSessionStore;

#[async_trait]
impl SessionStore for FailingSessionStore {
    async fn load_session(&self, _id: &str) -> Result<Option<Session>, AuthError> {
        Ok(None)
    }
    async fn save_session(&self, _session: &Session) -> Result<(), AuthError> {
        Err(AuthError::Session("store unavailable".to_string()))
    }
    async fn delete_session(&self, _id: &str) -> Result<(), AuthError> {
        Err(AuthError::Session("store unavailable".to_string()))
    }
}

fn app_with_failing_store() -> Router {
    let session_store: Arc<dyn SessionStore> = Arc::new(FailingSessionStore);
    let engine = Engine::builder()
        .provider(OAuth2Flow::new(MockOAuthProvider))
        .session_store(session_store)
        .session_config(SessionConfig {
            secure: false,
            ..Default::default()
        })
        .build();
    let state = AppState {
        auth: engine.clone(),
    };
    Router::new()
        .merge(engine.axum_router())
        .layer(CookieManagerLayer::new())
        .with_state(state)
}

/// Runs `request` against `app` with logging captured.
async fn drive_capturing(app: Router, request: Request<Body>) -> (StatusCode, String) {
    let captured = capture::start();

    let resp = app.oneshot(request).await.unwrap();
    let status = resp.status();
    let logs = captured.contents();
    (status, logs)
}

/// A store that cannot persist the session turns a successful authentication
/// into a 500. The user authenticated fine; the failure is ours, and the log
/// has to say which.
#[tokio::test(flavor = "current_thread")]
async fn a_store_that_cannot_save_fails_the_login_and_says_why() {
    let app = app_with_failing_store();

    // A full login first, to obtain a genuine state cookie.
    let login_resp = app
        .clone()
        .oneshot(
            Request::builder()
                .uri("/auth/login/mock")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    let ak_state = set_cookie_value(&login_resp, "ak_state").expect("login sets ak_state");
    let state_param = login_resp
        .headers()
        .get(header::LOCATION)
        .and_then(|l| l.to_str().ok())
        .and_then(|l| l.split("state=").nth(1))
        .expect("the redirect carries a state parameter")
        .to_string();

    let (status, logs) = drive_capturing(
        app,
        Request::builder()
            .uri(format!(
                "/auth/callback/mock?code=valid-code&state={state_param}"
            ))
            .header(header::COOKIE, format!("ak_state={ak_state}"))
            .body(Body::empty())
            .unwrap(),
    )
    .await;

    assert_eq!(status, StatusCode::INTERNAL_SERVER_ERROR);
    assert!(
        logs.contains("failed to persist the session after a successful login"),
        "the store failure should be reported, and distinguished from an auth failure; got:\n{logs}"
    );
}

/// Logging out without a session cookie clears the cookie and succeeds. It is
/// a no-op, not a failure — which is worth stating, because it reads like one
/// in a support ticket.
#[tokio::test(flavor = "current_thread")]
async fn logging_out_without_a_session_is_a_no_op_and_says_so() {
    let (status, logs) = drive_capturing(
        build_app(),
        Request::builder()
            .uri("/auth/logout")
            .body(Body::empty())
            .unwrap(),
    )
    .await;

    assert!(
        status.is_redirection(),
        "a logout with no session should still redirect, got {status}"
    );
    assert!(
        logs.contains("logout with no session cookie present"),
        "the no-op case should be visible; got:\n{logs}"
    );
}

/// And a store that cannot delete turns logout into a 500 rather than
/// silently leaving the session live.
#[tokio::test(flavor = "current_thread")]
async fn a_store_that_cannot_delete_fails_the_logout_and_says_why() {
    let cookie_name = SessionConfig::default().cookie_name;
    let (status, logs) = drive_capturing(
        app_with_failing_store(),
        Request::builder()
            .uri("/auth/logout")
            .header(header::COOKIE, format!("{cookie_name}=some-session-id"))
            .body(Body::empty())
            .unwrap(),
    )
    .await;

    assert_eq!(status, StatusCode::INTERNAL_SERVER_ERROR);
    assert!(
        logs.contains("failed to delete the session during logout"),
        "a failed deletion must not pass for a successful logout; got:\n{logs}"
    );
}

/// Expired sessions are rejected with 401 and removed from the session store by the Axum extractor.
#[tokio::test]
async fn expired_session_in_axum_extractor_is_rejected_and_cleaned_up() {
    let session_store = Arc::new(TestSessionStore::default());
    let expired_session = Session::new(
        "expired-session-id".to_string(),
        Identity {
            provider_id: "mock".to_string(),
            external_id: "user-42".to_string(),
            email: None,
            username: None,
            attributes: HashMap::new(),
        },
        chrono::Utc::now() - chrono::Duration::minutes(5),
    );
    session_store.save_session(&expired_session).await.unwrap();

    let engine = Engine::builder()
        .provider(OAuth2Flow::new(MockOAuthProvider))
        .session_store(session_store.clone() as Arc<dyn SessionStore>)
        .session_config(SessionConfig {
            secure: false,
            ..Default::default()
        })
        .build();
    let state = AppState {
        auth: engine.clone(),
    };
    let app = Router::new()
        .route("/protected", get(protected))
        .merge(engine.axum_router())
        .layer(CookieManagerLayer::new())
        .with_state(state);

    let cookie_name = SessionConfig::default().cookie_name;
    let resp = app
        .oneshot(
            Request::builder()
                .uri("/protected")
                .header(header::COOKIE, format!("{cookie_name}=expired-session-id"))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(resp.status(), StatusCode::UNAUTHORIZED);
    assert!(session_store
        .sessions
        .lock()
        .unwrap()
        .get("expired-session-id")
        .is_none());
}

/// Unsafe `success_url` query values are ignored during login and fall back to `/` on callback.
#[tokio::test]
async fn unsafe_success_url_is_sanitized_to_default_redirect() {
    let app = build_app();

    // 1. Initiate login with an open redirect target
    let resp = app
        .clone()
        .oneshot(
            Request::builder()
                .uri("/auth/login/mock?success_url=https://attacker.com")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(resp.status(), StatusCode::SEE_OTHER);
    let state_cookie = set_cookie_value(&resp, "ak_state").expect("must set ak_state cookie");
    let state_param = resp
        .headers()
        .get(header::LOCATION)
        .and_then(|l| l.to_str().ok())
        .and_then(|l| l.split("state=").nth(1))
        .expect("the redirect carries a state parameter")
        .to_string();

    // 2. Callback should redirect to "/" rather than "https://attacker.com"
    let callback_resp = app
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/auth/callback/mock?code=valid-code&state={state_param}"
                ))
                .header(header::COOKIE, format!("ak_state={state_cookie}"))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(callback_resp.status(), StatusCode::SEE_OTHER);
    let location = callback_resp
        .headers()
        .get(header::LOCATION)
        .unwrap()
        .to_str()
        .unwrap();
    assert_eq!(location, "/");
}

