/// Cross-site logout requests carrying `Sec-Fetch-Site: cross-site` are rejected with 401.
#[tokio::test]
async fn logout_rejects_cross_site_fetch_metadata() {
    let app = build_app();
    let cookie_name = SessionConfig::default().cookie_name;

    // Cross-site GET
    let resp = app
        .clone()
        .oneshot(
            Request::builder()
                .method("GET")
                .uri("/auth/logout")
                .header(header::COOKIE, format!("{cookie_name}=test-session-id"))
                .header("sec-fetch-site", "cross-site")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(resp.status(), StatusCode::UNAUTHORIZED);

    // Cross-site POST
    let resp_post = app
        .clone()
        .oneshot(
            Request::builder()
                .method("POST")
                .uri("/auth/logout")
                .header(header::COOKIE, format!("{cookie_name}=test-session-id"))
                .header("sec-fetch-site", "cross-site")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(resp_post.status(), StatusCode::UNAUTHORIZED);
}

